INSERT INTO `pipeline_versions` VALUES ('586b8652-bf56-4b25-8bdf-a61bb38b52af',1793737519,'tutorial-data-passing-in-python-components','[Tutorial] Data passing in python components','[]','0142974f-f81e-4b46-b95e-c6d2784fffd5','READY','','[source code](https://github.com/kubeflow/pipelines/tree/555bfa60a70da88c594960bdacfd78fa7c061043/samples/tutorials/Data%20passing%20in%20python%20components) Shows how to pass data between python components.','components:\n  comp-preprocess:\n    executorLabel: exec-preprocess\n    inputDefinitions:\n      parameters:\n        message:\n          parameterType: STRING\n    outputDefinitions:\n      artifacts:\n        output_dataset_one:\n          artifactType:\n            schemaTitle: system.Dataset\n            schemaVersion: 0.0.1\n        output_dataset_two_path:\n          artifactType:\n            schemaTitle: system.Dataset\n            schemaVersion: 0.0.1\n      parameters:\n        output_bool_parameter_path:\n          parameterType: BOOLEAN\n        output_dict_parameter_path:\n          parameterType: STRUCT\n        output_list_parameter_path:\n          parameterType: LIST\n        output_parameter_path:\n          parameterType: STRING\n  comp-train:\n    executorLabel: exec-train\n    inputDefinitions:\n      artifacts:\n        dataset_one_path:\n          artifactType:\n            schemaTitle: system.Dataset\n            schemaVersion: 0.0.1\n        dataset_two:\n          artifactType:\n            schemaTitle: system.Dataset\n            schemaVersion: 0.0.1\n      parameters:\n        input_bool:\n          parameterType: BOOLEAN\n        input_dict:\n          parameterType: STRUCT\n        input_list:\n          parameterType: LIST\n        message:\n          parameterType: STRING\n        num_steps:\n          defaultValue: 100\n          isOptional: true\n          parameterType: NUMBER_INTEGER\n    outputDefinitions:\n      artifacts:\n        model:\n          artifactType:\n            schemaTitle: system.Model\n            schemaVersion: 0.0.1\ndeploymentSpec:\n  executors:\n    exec-preprocess:\n      container:\n        args:\n        - --executor_input\n        - \'{{$}}\'\n        - --function_to_execute\n        - preprocess\n        command:\n        - sh\n        - -c\n        - |2\n\n          if ! [ -x \"$(command -v pip)\" ]; then\n              python3 -m ensurepip || python3 -m ensurepip --user || apt-get install python3-pip\n          fi\n\n          PIP_DISABLE_PIP_VERSION_CHECK=1 python3 -m pip install --quiet --no-warn-script-location \'kfp==2.16.0\' \'--no-deps\' \'typing-extensions>=3.7.4,<5; python_version<\"3.9\"\' && \"$0\" \"$@\"\n        - sh\n        - -ec\n        - |\n          program_path=$(mktemp -d)\n\n          printf \"%s\" \"$0\" > \"$program_path/ephemeral_component.py\"\n          _KFP_RUNTIME=true python3 -m kfp.dsl.executor_main                         --component_module_path                         \"$program_path/ephemeral_component.py\"                         \"$@\"\n        - |2+\n\n          import kfp\n          from kfp import dsl\n          from kfp.dsl import *\n          from typing import *\n\n          def preprocess(\n              # An input parameter of type string.\n              message: str,\n              # Use Output[T] to get a metadata-rich handle to the output artifact\n              # of type `Dataset`.\n              output_dataset_one: Output[Dataset],\n              # A locally accessible filepath for another output artifact of type\n              # `Dataset`.\n              output_dataset_two_path: OutputPath(\'Dataset\'),\n              # A locally accessible filepath for an output parameter of type string.\n              output_parameter_path: OutputPath(str),\n              # A locally accessible filepath for an output parameter of type bool.\n              output_bool_parameter_path: OutputPath(bool),\n              # A locally accessible filepath for an output parameter of type dict.\n              output_dict_parameter_path: OutputPath(Dict[str, int]),\n              # A locally accessible filepath for an output parameter of type list.\n              output_list_parameter_path: OutputPath(List[str]),\n          ):\n              \"\"\"Dummy preprocessing step.\"\"\"\n\n              # Use Dataset.path to access a local file path for writing.\n              # One can also use Dataset.uri to access the actual URI file path.\n              with open(output_dataset_one.path, \'w\') as f:\n                  f.write(message)\n\n              # OutputPath is used to just pass the local file path of the output artifact\n              # to the function.\n              with open(output_dataset_two_path, \'w\') as f:\n                  f.write(message)\n\n              with open(output_parameter_path, \'w\') as f:\n                  f.write(message)\n\n              with open(output_bool_parameter_path, \'w\') as f:\n                  f.write(\n                      str(True))  # use either `str()` or `json.dumps()` for bool values.\n\n              import json\n              with open(output_dict_parameter_path, \'w\') as f:\n                  f.write(json.dumps({\'A\': 1, \'B\': 2}))\n\n              with open(output_list_parameter_path, \'w\') as f:\n                  f.write(json.dumps([\'a\', \'b\', \'c\']))\n\n        image: python:3.11\n    exec-train:\n      container:\n        args:\n        - --executor_input\n        - \'{{$}}\'\n        - --function_to_execute\n        - train\n        command:\n        - sh\n        - -c\n        - |2\n\n          if ! [ -x \"$(command -v pip)\" ]; then\n              python3 -m ensurepip || python3 -m ensurepip --user || apt-get install python3-pip\n          fi\n\n          PIP_DISABLE_PIP_VERSION_CHECK=1 python3 -m pip install --quiet --no-warn-script-location \'kfp==2.16.0\' \'--no-deps\' \'typing-extensions>=3.7.4,<5; python_version<\"3.9\"\' && \"$0\" \"$@\"\n        - sh\n        - -ec\n        - |\n          program_path=$(mktemp -d)\n\n          printf \"%s\" \"$0\" > \"$program_path/ephemeral_component.py\"\n          _KFP_RUNTIME=true python3 -m kfp.dsl.executor_main                         --component_module_path                         \"$program_path/ephemeral_component.py\"                         \"$@\"\n        - |2+\n\n          import kfp\n          from kfp import dsl\n          from kfp.dsl import *\n          from typing import *\n\n          def train(\n              # Use InputPath to get a locally accessible path for the input artifact\n              # of type `Dataset`.\n              dataset_one_path: InputPath(\'Dataset\'),\n              # Use Input[T] to get a metadata-rich handle to the input artifact\n              # of type `Dataset`.\n              dataset_two: Input[Dataset],\n              # An input parameter of type string.\n              message: str,\n              # Use Output[T] to get a metadata-rich handle to the output artifact\n              # of type `Model`.\n              model: Output[Model],\n              # An input parameter of type bool.\n              input_bool: bool,\n              # An input parameter of type dict.\n              input_dict: Dict[str, int],\n              # An input parameter of type List[str].\n              input_list: List[str],\n              # An input parameter of type int with a default value.\n              num_steps: int = 100,\n          ):\n              \"\"\"Dummy Training step.\"\"\"\n              with open(dataset_one_path, \'r\') as input_file:\n                  dataset_one_contents = input_file.read()\n\n              with open(dataset_two.path, \'r\') as input_file:\n                  dataset_two_contents = input_file.read()\n\n              line = (f\'dataset_one_contents: {dataset_one_contents} || \'\n                      f\'dataset_two_contents: {dataset_two_contents} || \'\n                      f\'message: {message} || \'\n                      f\'input_bool: {input_bool}, type {type(input_bool)} || \'\n                      f\'input_dict: {input_dict}, type {type(input_dict)} || \'\n                      f\'input_list: {input_list}, type {type(input_list)} \\n\')\n\n              with open(model.path, \'w\') as output_file:\n                  for i in range(num_steps):\n                      output_file.write(\'Step {}\\n{}\\n=====\\n\'.format(i, line))\n\n              # model is an instance of Model artifact, which has a .metadata dictionary\n              # to store arbitrary metadata for the output artifact.\n              model.metadata[\'accuracy\'] = 0.9\n\n        image: python:3.11\npipelineInfo:\n  name: tutorial-data-passing\nroot:\n  dag:\n    tasks:\n      preprocess:\n        cachingOptions:\n          enableCache: true\n        componentRef:\n          name: comp-preprocess\n        inputs:\n          parameters:\n            message:\n              componentInputParameter: message\n        taskInfo:\n          name: preprocess\n      train:\n        cachingOptions:\n          enableCache: true\n        componentRef:\n          name: comp-train\n        dependentTasks:\n        - preprocess\n        inputs:\n          artifacts:\n            dataset_one_path:\n              taskOutputArtifact:\n                outputArtifactKey: output_dataset_one\n                producerTask: preprocess\n            dataset_two:\n              taskOutputArtifact:\n                outputArtifactKey: output_dataset_two_path\n                producerTask: preprocess\n          parameters:\n            input_bool:\n              taskOutputParameter:\n                outputParameterKey: output_bool_parameter_path\n                producerTask: preprocess\n            input_dict:\n              taskOutputParameter:\n                outputParameterKey: output_dict_parameter_path\n                producerTask: preprocess\n            input_list:\n              taskOutputParameter:\n                outputParameterKey: output_list_parameter_path\n                producerTask: preprocess\n            message:\n              taskOutputParameter:\n                outputParameterKey: output_parameter_path\n                producerTask: preprocess\n        taskInfo:\n          name: train\n  inputDefinitions:\n    parameters:\n      message:\n        defaultValue: message\n        isOptional: true\n        parameterType: STRING\nschemaVersion: 2.1.0\nsdkVersion: kfp-2.16.0\n',''),('7982dd1c-6aa9-45a3-8e6a-ec3ff306f8d9',1793737519,'tutorial-dsl-control-structures','[Tutorial] DSL - Control structures','[]','3d064d4f-3f56-468f-932e-8e413c32ebcb','READY','','[source code](https://github.com/kubeflow/pipelines/tree/555bfa60a70da88c594960bdacfd78fa7c061043/samples/tutorials/DSL%20-%20Control%20structures) Shows how to use conditional execution and exit handlers. This pipeline will randomly fail to demonstrate that the exit handler gets executed even in case of failure.','components:\n  comp-condition-4:\n    dag:\n      tasks:\n        condition-5:\n          componentRef:\n            name: comp-condition-5\n          dependentTasks:\n          - get-random-int-op\n          inputs:\n            parameters:\n              pipelinechannel--flip-coin-op-Output:\n                componentInputParameter: pipelinechannel--flip-coin-op-Output\n              pipelinechannel--get-random-int-op-Output:\n                taskOutputParameter:\n                  outputParameterKey: Output\n                  producerTask: get-random-int-op\n              pipelinechannel--loop-item-param-2:\n                componentInputParameter: pipelinechannel--loop-item-param-2\n          taskInfo:\n            name: condition-5\n          triggerPolicy:\n            condition: int(inputs.parameter_values[\'pipelinechannel--get-random-int-op-Output\'])\n              > 5\n        condition-6:\n          componentRef:\n            name: comp-condition-6\n          dependentTasks:\n          - get-random-int-op\n          inputs:\n            parameters:\n              pipelinechannel--flip-coin-op-Output:\n                componentInputParameter: pipelinechannel--flip-coin-op-Output\n              pipelinechannel--get-random-int-op-Output:\n                taskOutputParameter:\n                  outputParameterKey: Output\n                  producerTask: get-random-int-op\n              pipelinechannel--loop-item-param-2:\n                componentInputParameter: pipelinechannel--loop-item-param-2\n          taskInfo:\n            name: condition-6\n          triggerPolicy:\n            condition: int(inputs.parameter_values[\'pipelinechannel--get-random-int-op-Output\'])\n              <= 5\n        get-random-int-op:\n          cachingOptions:\n            enableCache: true\n          componentRef:\n            name: comp-get-random-int-op\n          inputs:\n            parameters:\n              maximum:\n                runtimeValue:\n                  constant: 9\n              minimum:\n                runtimeValue:\n                  constant: 0\n          taskInfo:\n            name: get-random-int-op\n    inputDefinitions:\n      parameters:\n        pipelinechannel--flip-coin-op-Output:\n          parameterType: STRING\n        pipelinechannel--loop-item-param-2:\n          parameterType: STRING\n  comp-condition-5:\n    dag:\n      tasks:\n        print-op-2:\n          cachingOptions:\n            enableCache: true\n          componentRef:\n            name: comp-print-op-2\n          inputs:\n            parameters:\n              message:\n                runtimeValue:\n                  constant: \'{{$.inputs.parameters[\'\'pipelinechannel--loop-item-param-2\'\']}}\n                    and {{$.inputs.parameters[\'\'pipelinechannel--get-random-int-op-Output\'\']}}\n                    > 5!\'\n              pipelinechannel--get-random-int-op-Output:\n                componentInputParameter: pipelinechannel--get-random-int-op-Output\n              pipelinechannel--loop-item-param-2:\n                componentInputParameter: pipelinechannel--loop-item-param-2\n          taskInfo:\n            name: print-op-2\n    inputDefinitions:\n      parameters:\n        pipelinechannel--flip-coin-op-Output:\n          parameterType: STRING\n        pipelinechannel--get-random-int-op-Output:\n          parameterType: NUMBER_INTEGER\n        pipelinechannel--loop-item-param-2:\n          parameterType: STRING\n  comp-condition-6:\n    dag:\n      tasks:\n        print-op-3:\n          cachingOptions:\n            enableCache: true\n          componentRef:\n            name: comp-print-op-3\n          inputs:\n            parameters:\n              message:\n                runtimeValue:\n                  constant: \'{{$.inputs.parameters[\'\'pipelinechannel--loop-item-param-2\'\']}}\n                    and {{$.inputs.parameters[\'\'pipelinechannel--get-random-int-op-Output\'\']}}\n                    <= 5!\'\n              pipelinechannel--get-random-int-op-Output:\n                componentInputParameter: pipelinechannel--get-random-int-op-Output\n              pipelinechannel--loop-item-param-2:\n                componentInputParameter: pipelinechannel--loop-item-param-2\n          taskInfo:\n            name: print-op-3\n    inputDefinitions:\n      parameters:\n        pipelinechannel--flip-coin-op-Output:\n          parameterType: STRING\n        pipelinechannel--get-random-int-op-Output:\n          parameterType: NUMBER_INTEGER\n        pipelinechannel--loop-item-param-2:\n          parameterType: STRING\n  comp-exit-handler-1:\n    dag:\n      tasks:\n        fail-op:\n          cachingOptions:\n            enableCache: true\n          componentRef:\n            name: comp-fail-op\n          inputs:\n            parameters:\n              message:\n                runtimeValue:\n                  constant: Failing the run to demonstrate that exit handler still\n                    gets executed.\n          taskInfo:\n            name: fail-op\n  comp-fail-op:\n    executorLabel: exec-fail-op\n    inputDefinitions:\n      parameters:\n        message:\n          parameterType: STRING\n  comp-flip-coin-op:\n    executorLabel: exec-flip-coin-op\n    outputDefinitions:\n      parameters:\n        Output:\n          parameterType: STRING\n  comp-for-loop-3:\n    dag:\n      tasks:\n        condition-4:\n          componentRef:\n            name: comp-condition-4\n          inputs:\n            parameters:\n              pipelinechannel--flip-coin-op-Output:\n                componentInputParameter: pipelinechannel--flip-coin-op-Output\n              pipelinechannel--loop-item-param-2:\n                componentInputParameter: pipelinechannel--loop-item-param-2\n          taskInfo:\n            name: condition-4\n          triggerPolicy:\n            condition: inputs.parameter_values[\'pipelinechannel--loop-item-param-2\']\n              == inputs.parameter_values[\'pipelinechannel--flip-coin-op-Output\']\n    inputDefinitions:\n      parameters:\n        pipelinechannel--flip-coin-op-Output:\n          parameterType: STRING\n        pipelinechannel--loop-item-param-2:\n          parameterType: STRING\n  comp-get-random-int-op:\n    executorLabel: exec-get-random-int-op\n    inputDefinitions:\n      parameters:\n        maximum:\n          parameterType: NUMBER_INTEGER\n        minimum:\n          parameterType: NUMBER_INTEGER\n    outputDefinitions:\n      parameters:\n        Output:\n          parameterType: NUMBER_INTEGER\n  comp-print-op:\n    executorLabel: exec-print-op\n    inputDefinitions:\n      parameters:\n        message:\n          parameterType: STRING\n  comp-print-op-2:\n    executorLabel: exec-print-op-2\n    inputDefinitions:\n      parameters:\n        message:\n          parameterType: STRING\n  comp-print-op-3:\n    executorLabel: exec-print-op-3\n    inputDefinitions:\n      parameters:\n        message:\n          parameterType: STRING\ndeploymentSpec:\n  executors:\n    exec-fail-op:\n      con